const data = $('Extract Error Data').item.json;
const memoryContext = $('Memory Read').first().json.memoryContext || 'Nenhuma memoria recente.';
const failedNode = data.failed_node;

// ---- GROUNDING: evidencia real puxada via API (best-effort; nunca quebra o alerta) ----
let nodeCode = null, errorDetail = null, dataTrail = null;
try {
  const wf = $('Fetch Workflow Def').first().json;
  const nodes = (wf && wf.nodes) || [];
  const fn = nodes.find(n => n.name === failedNode);
  if (fn) {
    nodeCode = (fn.parameters && (fn.parameters.jsCode || fn.parameters.functionCode)) || null;
    if (!nodeCode) nodeCode = '(node nao-Code, tipo ' + fn.type + ') params: ' + JSON.stringify(fn.parameters || {}).slice(0, 800);
  }
} catch (e) {}
try {
  const ex = $('Fetch Execution Data').first().json;
  const rd = ex && ex.data && ex.data.resultData && ex.data.resultData.runData;
  if (rd) {
    const fr = rd[failedNode];
    if (fr && fr[0] && fr[0].error) {
      errorDetail = (fr[0].error.message || '') + (fr[0].error.description ? ' | ' + fr[0].error.description : '');
    }
    const parts = [];
    for (const nm of Object.keys(rd)) {
      try {
        const j = rd[nm][0].data.main[0][0].json;
        parts.push(nm + ': ' + JSON.stringify(j).slice(0, 400));
      } catch (e) {}
    }
    dataTrail = parts.join('\n').slice(0, 2500);
  }
} catch (e) {}

const evidenceOk = !!(nodeCode || errorDetail || dataTrail);
const evidenceBlock = evidenceOk
  ? `EVIDENCIA REAL (puxada da execution via API — usa isto como base factual):

Codigo do node que falhou (${failedNode}):
${nodeCode || '(indisponivel)'}

Erro detalhado: ${errorDetail || data.error_message}

Dados que passaram pelos nodes (truncado):
${dataTrail || '(indisponivel)'}`
  : `EVIDENCIA REAL: INDISPONIVEL (recolha via API falhou). So tens a mensagem de erro. NAO inventes codigo/schema/linhas; Confianca = BAIXA.`;

const prompt = `Voce e o n8n-doctor, diagnosticador de erros de workflows n8n. Responde em PT-PT, directo, sem fluff.

REGRAS ANTI-ALUCINACAO (obrigatorias):
- Baseia o diagnostico na EVIDENCIA REAL abaixo quando disponivel (codigo do node + dados reais). Cita o que ves.
- NAO inventes nomes de campos, schemas, numeros de linha, ou conteudo de codigo que NAO esteja na EVIDENCIA REAL.
- Numeros de linha: usa SO os que aparecem no codigo fornecido.
- Se a EVIDENCIA REAL estiver indisponivel, diagnostica so pela mensagem de erro e marca Confianca BAIXA. Melhor "nao sei, inspecciona X" do que um fix inventado.

CHECKLIST n8n-doctor (heuristicas, nao prova):
- HTTP 4xx em Supabase/HTTP Request = payload/parametros ou constraint de DB (check/NOT NULL). Ve o body real.
- HTTP 401/403 = auth (token/secret/credential expirado ou em falta).
- Timeout/ECONNRESET/socket = TRANSIENT (rede, rate limit, servico lento).
- throw num node Code = validacao intencional; o root cause esta no INPUT que chegou ao node (ve os dados reais), nao no node.
- "Bad request - please check your parameters" em Supabase/Postgres = constraint violada; a descricao costuma dizer qual.

${evidenceBlock}

${memoryContext}

NOTA MEMORIA CRUZADA: memorias podem ser de outras instancias (Hetzner/Railway/Oracle). Transferiveis: infra partilhada (Supabase, Anthropic, OpenAI, Evolution, Chatwoot, Airtable), logica, padroes, bugs de nodes nativos. NAO transferiveis: IDs de credentials/workflow, URLs de webhook, paths locais, env vars, network do host. Instancia diferente + erro NAO transferivel = ignora; se transferivel, peso reduzido.

ERRO DETECTADO:
Workflow: ${data.workflow_name} (ID: ${data.workflow_id})
Node: ${data.failed_node}
Error: ${data.error_message}
Execution ID: ${data.execution_id}
Instancia: n8n-hetzner (workflows.coletiv.me)

TAREFAS:
1. DIAGNOSTICA o root cause a partir da EVIDENCIA REAL.
2. Severidade: CRITICO | WARNING | INFO
3. Tipo: TRANSIENT | PERSISTENT
4. CONFIANCA: ALTA (tenho evidencia e causa clara) | MEDIA (provavel, evidencia parcial) | BAIXA (so a mensagem)
5. Fix: HIPOTESE com passos a verificar.
6. Se a memoria mostra este MESMO erro/workflow repetido: escala severidade.

FORMATO (max 200 palavras):

Severidade: [CRITICO | WARNING | INFO]
Tipo: [TRANSIENT | PERSISTENT]
Confianca: [ALTA | MEDIA | BAIXA]
Auto-fix: [SIM | NAO]

Root Cause (do que a evidencia mostra):
[1-2 frases. Se especulares, prefixa "ESPECULACAO:".]

Fix Sugerido (HIPOTESE — verificar antes de aplicar):
[passos a verificar]

Accao Necessaria:
[automatico / manual / monitorar]`;

return [{ json: { prompt, timeout: 90000, workflow_id: data.workflow_id, error_message: data.error_message } }];

